-- Additive migration. Legacy profiles are preserved and are never auto-subscribed.
BEGIN;

CREATE TABLE IF NOT EXISTS newsletter_zones (id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL, country TEXT NOT NULL, currency TEXT NOT NULL, language TEXT NOT NULL, status TEXT NOT NULL, send_day INTEGER NOT NULL, send_hour INTEGER NOT NULL);
INSERT INTO newsletter_zones(id,name,timezone,country,currency,language,status,send_day,send_hour) VALUES('pays-de-gex','Pays de Gex','Europe/Paris','FR','EUR','fr','active',4,8) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS subscribers (id TEXT PRIMARY KEY, email TEXT NOT NULL, email_hash TEXT NOT NULL, zone TEXT NOT NULL REFERENCES newsletter_zones(id), confirmed_at BIGINT, unsubscribed_at BIGINT, created_at BIGINT NOT NULL, UNIQUE(email_hash,zone));
CREATE TABLE IF NOT EXISTS subscriber_consents (id TEXT PRIMARY KEY, subscriber_id TEXT NOT NULL REFERENCES subscribers(id) ON DELETE CASCADE, kind TEXT NOT NULL, version TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriber_tokens (hash TEXT PRIMARY KEY, subscriber_id TEXT NOT NULL REFERENCES subscribers(id) ON DELETE CASCADE, purpose TEXT NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS zone_newsletters (id TEXT PRIMARY KEY, zone TEXT NOT NULL REFERENCES newsletter_zones(id), weekend TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, preparation_status TEXT NOT NULL, send_status TEXT NOT NULL DEFAULT 'not_scheduled', approved_revision INTEGER, scheduled_at BIGINT, content TEXT, error TEXT, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, UNIQUE(zone,weekend));
CREATE TABLE IF NOT EXISTS newsletter_jobs (id TEXT PRIMARY KEY, newsletter_id TEXT NOT NULL UNIQUE REFERENCES zone_newsletters(id) ON DELETE CASCADE, status TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 0, run_after BIGINT NOT NULL, lease TEXT, locked_until BIGINT, error TEXT, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS newsletter_jobs_ready ON newsletter_jobs(status,run_after);
CREATE TABLE IF NOT EXISTS newsletter_attempts (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES newsletter_jobs(id) ON DELETE CASCADE, attempt INTEGER NOT NULL, state TEXT NOT NULL, error TEXT, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS newsletter_sources (id TEXT PRIMARY KEY, zone TEXT NOT NULL REFERENCES newsletter_zones(id), name TEXT NOT NULL, url TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(zone,url));
CREATE TABLE IF NOT EXISTS newsletter_deliveries (id TEXT PRIMARY KEY, newsletter_id TEXT NOT NULL REFERENCES zone_newsletters(id) ON DELETE CASCADE, subscriber_id TEXT NOT NULL REFERENCES subscribers(id) ON DELETE CASCADE, revision INTEGER NOT NULL, state TEXT NOT NULL, payload TEXT, first_attempt_at BIGINT, error TEXT, updated_at BIGINT NOT NULL, UNIQUE(newsletter_id,subscriber_id));
CREATE TABLE IF NOT EXISTS newsletter_delivery_attempts (id TEXT PRIMARY KEY, delivery_id TEXT NOT NULL REFERENCES newsletter_deliveries(id) ON DELETE CASCADE, state TEXT NOT NULL, error TEXT, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS newsletter_audit (id TEXT PRIMARY KEY, newsletter_id TEXT NOT NULL REFERENCES zone_newsletters(id) ON DELETE CASCADE, action TEXT NOT NULL, actor TEXT NOT NULL, revision INTEGER NOT NULL, created_at BIGINT NOT NULL);
INSERT INTO newsletter_sources(id,zone,name,url,enabled,notes,created_at) VALUES('gex-tourisme','pays-de-gex','Pays de Gex – Monts Jura : agenda','https://www.paysdegex-montsjura.com/agenda-animations/tout-lagenda/',1,'Source fournie par le porteur du projet. Office de tourisme : agenda général. Aucune couverture exhaustive garantie.',0) ON CONFLICT(id) DO NOTHING;

ALTER TABLE public.newsletter_zones ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.newsletter_zones FROM anon, authenticated;
CREATE POLICY deny_client_access ON public.newsletter_zones FOR ALL TO anon, authenticated USING (false) WITH CHECK (false);
ALTER TABLE public.subscribers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.subscribers FROM anon, authenticated;
