REVOKE ALL ON public.newsletter_deliveries FROM anon, authenticated;
CREATE POLICY deny_client_access ON public.newsletter_deliveries FOR ALL TO anon, authenticated USING (false) WITH CHECK (false);
ALTER TABLE public.newsletter_delivery_attempts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.newsletter_delivery_attempts FROM anon, authenticated;
