ALTER TABLE public.newsletter_audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.newsletter_audit FROM anon, authenticated;
CREATE POLICY deny_client_access ON public.newsletter_audit FOR ALL TO anon, authenticated USING (false) WITH CHECK (false);
COMMIT;
